window.docContents[191].resolve({"/Ch04GoalManagement/#context-solution":{"contents":"-- [示意]\nelab \"safe_tactic\" : tactic => do\n  withMainContext do        -- 自动切换到主目标的上下文\n    let target ← getMainTarget\n    -- 这里的 getLCtx 保证是主目标的局部上下文\n    let lctx ← getLCtx\n    -- ... 在正确的上下文中操作 ...\n\n\nwithMainContext 的实现等价于 getMainGoal >>= fun g => g.withContext。它做了两件事：取出主目标，然后在该目标的局部上下文中执行后续代码。这样你在 do 块中调用 getLCtx、getLocalDecl 等 API 时，总是能拿到正确的上下文。\n\n","context":"Lean 4 自动化内幕\u0009目标管理\u00094.6  withMainContext  模式","header":"6.7.2. 解决方案","id":"/Ch04GoalManagement/#context-solution"},"/Ch19DesignYourOwn/#mono-add-core-recursion":{"contents":"-- [示意] mono_add 核心逻辑\npartial def proveLE (lhs rhs : Expr) : TacticM Expr := do\n  -- ❶ 相等 → le_refl\n  if ← isDefEq lhs rhs then\n    mkAppM ``le_refl #[lhs]\n  -- ❷ 加法 → 拆解两边\n  else if let some (a, c) ← matchAdd lhs then\n    if let some (b, d) ← matchAdd rhs then\n      let hab ← proveLE a b       -- 递归证明 a ≤ b\n      let hcd ← proveLE c d       -- 递归证明 c ≤ d\n      mkAppM ``add_le_add #[hab, hcd]\n    else searchHypothesis lhs rhs\n  -- ❸ 回退 → 在上下文中搜索匹配假设\n  else searchHypothesis lhs rhs\n\n\n","context":"Lean 4 自动化内幕\u0009设计你自己的领域自动化\u000919.4 完整示例：微型  mono_add  tactic","header":"21.4.2. 第二步：核心递归","id":"/Ch19DesignYourOwn/#mono-add-core-recursion"},"/Ch20Reflection/#exercise-identify-four-steps":{"contents":"标出以下代码中哪些部分对应 ❶语法、❷语义、❸范式化、❹正确性：\n\n-- [示意]\ninductive PExpr                    -- (?)\n- var (i : Nat)：add (a b : PExpr)\n\ndef PExpr.eval (env : Nat → ℕ) : PExpr → ℕ     -- (?)\n- .var i => env i：.add a b => a.eval env + b.eval env\n\ndef PExpr.sort : PExpr → PExpr := ...            -- (?)\n\ntheorem sort_sound (e : PExpr) (env : Nat → ℕ) : -- (?)\n    (e.sort).eval env = e.eval env := ...\n\n\n","context":"Lean 4 自动化内幕\u0009反射证明模式\u000920.10 练习","header":"22.10.1. 练习 1（基础 · §20.2 复习）：识别四步模式","id":"/Ch20Reflection/#exercise-identify-four-steps"}});